            row.append(count)
        else:
            total = sums[item.column]
            if total == total.to_integral_value():
                row.append(int(total))
            else:
                row.append(_JsonNumber(format(total, "f")))
    return {
        "columns": [item.text for item in query.select],
        "rows": [row],
